#include <stdatomic.h>
#define CHUNK (128*1024)
#define MAXCH 4096
static uint64_t HS[MAXCH*3];
static struct { const uint32_t *st; const uint64_t *r,*rp; const uint8_t *in; uint8_t *out; size_t len,nch; uint64_t *hs; _Atomic size_t next; } G;
static void do_chunks(void){
  for(;;){
    size_t i=atomic_fetch_add(&G.next,1);
    if(i>=G.nch) break;
    job_t j; j.st=G.st; j.r=G.r; j.rp=G.rp; j.in=G.in; j.out=G.out; j.off=i*CHUNK;
    j.len=(i==G.nch-1)?G.len-i*CHUNK:CHUNK;
    worker(&j);
    G.hs[3*i]=j.h[0];G.hs[3*i+1]=j.h[1];G.hs[3*i+2]=j.h[2];
  }
}
static pthread_mutex_t PM=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t PC=PTHREAD_COND_INITIALIZER, PD=PTHREAD_COND_INITIALIZER;
static int NSTARTED=0; static unsigned long GEN=0; static int WANT=0; static int ACTIVE=0;
static void *pool_thread(void *arg){
  long id=(long)arg; unsigned long seen=0;
  pthread_mutex_lock(&PM);
  for(;;){
    while(GEN==seen || id>=WANT){ if(GEN!=seen) seen=GEN; pthread_cond_wait(&PC,&PM); }
    seen=GEN;
    pthread_mutex_unlock(&PM);
    do_chunks();
    pthread_mutex_lock(&PM);
    if(--ACTIVE==0) pthread_cond_signal(&PD);
  }
  return NULL;
}
static void pool_run(int T){
  /* T-1 helper threads + caller */
  pthread_mutex_lock(&PM);
  while(NSTARTED<T-1){ pthread_t t; pthread_create(&t,NULL,pool_thread,(void*)(long)NSTARTED); pthread_detach(t); NSTARTED++; }
  WANT=T-1; ACTIVE=T-1; GEN++;
  pthread_cond_broadcast(&PC);
  pthread_mutex_unlock(&PM);
  do_chunks();
  pthread_mutex_lock(&PM);
  while(ACTIVE>0) pthread_cond_wait(&PD,&PM);
  pthread_mutex_unlock(&PM);
}
